// Retrato en vivo: procesamiento local, sin grabación ni envío de imágenes.
window.PortraitCamera = (() => {
  let stream=null, frame=0, session=0, active=false, frozen=false, last=0, mode='ash';
  let canvas, ctx, video, source, sourceCtx, status, start, capture, freeze, strength, grain, distortion, demoButton, demoImage, demoActive=false, warpBuffer, fieldX=.5, fieldY=.46;
  let lut=new Uint8ClampedArray(768);
  const palettes={ash:[[6,6,6],[32,32,32],[74,74,74],[126,126,126],[196,194,190],[241,237,229]]};
  function color(t){const p=palettes.ash,n=Math.max(0,Math.min(.999,t))*(p.length-1),i=Math.floor(n),a=n-i;return p[i].map((v,c)=>v+(p[Math.min(i+1,p.length-1)][c]-v)*a)}
  function updatePalette(){for(let i=0;i<256;i++){const rgb=color(i/255);for(let c=0;c<3;c++)lut[i*3+c]=rgb[c]}}
  function markup(){return `<div class="camera-layout"><div class="camera-heading"><div><p class="eyebrow">03 / UN RETRATO DE LO QUE LLEVÁS ADENTRO</p><h2 id="modal-title">CÓMO TE VES<br><span>CUANDO TE MIRÁS.</span></h2></div><p>Acercate. Quedate un momento.<br>Dejá que aparezca otra versión de vos.</p></div><div class="camera-workspace"><div class="camera-stage"><canvas id="portrait-canvas" width="640" height="360" aria-label="Tu retrato con tratamiento gráfico en tiempo real"></canvas><div class="camera-stage-top"><span id="camera-signal">○ CÁMARA APAGADA</span><span>EL ODIO EN FRANCÉS / RETRATO 001</span></div><div class="raw-preview"><video id="camera-video" autoplay muted playsinline aria-label="Vista original de la cámara"></video><span id="raw-label">CÁMARA APAGADA</span></div><div class="camera-stage-bottom"><span>ADENTRO ≠ AFUERA</span><span>NO SOS UNA IMAGEN FIJA.</span></div></div><aside class="camera-controls"><p class="eyebrow">TU IMAGEN, OTRA LECTURA.</p><div class="camera-control-group"><span class="camera-label">01 / TRATAMIENTO</span><div class="palette-buttons"><button data-palette="bronca" aria-pressed="false"><i class="bronca-swatch"></i>MODO BRONCA</button><button data-palette="ash" aria-pressed="true"><i class="ash-swatch"></i>CENIZA</button></div></div><div class="camera-control-group"><label for="camera-strength">02 / CONTRASTE <output id="strength-value">65%</output></label><input id="camera-strength" type="range" min="0" max="100" value="65"></div><div class="camera-control-group"><label for="camera-grain">03 / GRANO <output id="grain-value">25%</output></label><input id="camera-grain" type="range" min="0" max="100" value="25"></div><div class="camera-control-group"><label for="camera-distortion">04 / DEFORMACIÓN <output id="distortion-value">70%</output></label><input id="camera-distortion" type="range" min="0" max="100" value="70"></div><p class="camera-note">Centrá tu cara en el visor. En Modo bronca, una malla deforma el retrato y suma grafismos originales. Mové el cursor o tocá para desplazar el efecto.</p><button class="pill camera-start" id="camera-start">PRENDER CÁMARA <span>↗</span></button><button class="camera-demo" id="camera-demo">PROBAR CON UNA FOTO ↗</button><div class="camera-secondary"><button id="camera-freeze" disabled>CONGELAR</button><button id="camera-capture" disabled>GUARDAR RETRATO ↓</button></div><p id="camera-status" role="status">Prendé la cámara para verte en tiempo real con el tratamiento gráfico.</p><p class="camera-privacy">SOLO EN TU DISPOSITIVO.<br>Sin audio. Sin grabación. Sin subir tu imagen.</p></aside></div><div class="camera-screen-footer"><span>LO QUE MOSTRÁS. LO QUE SENTÍS. TODO SOS VOS.</span><button data-modal="escribir">PONERLO EN PALABRAS ↗</button></div></div>`}
  function drawIdle(){ctx.fillStyle="#0b0b0b";ctx.fillRect(0,0,640,360);ctx.save();ctx.translate(55,100);ctx.rotate(-.035);ctx.font="700 87px Barlow Condensed, Impact, sans-serif";ctx.fillStyle="#eee9df";ctx.fillText("LO QUE",0,0);ctx.fillStyle="#ed3529";ctx.fillText("NO MOSTRÁS.",0,80);ctx.restore();ctx.font="10px DM Sans, sans-serif";ctx.fillStyle="#b4b0a9";ctx.fillText("PRENDÉ LA CÁMARA. MIRATE DE OTRA FORMA.",55,270);}
  function render(t=0){if(!canvas)return;if(t-last<50){frame=requestAnimationFrame(render);return}last=t;if(!frozen){if(active&&video.readyState>=2){const vw=video.videoWidth,vh=video.videoHeight;const crop=vw/vh>16/9?{w:vh*16/9,h:vh}:{w:vw,h:vw*9/16};sourceCtx.save();sourceCtx.translate(640,0);sourceCtx.scale(-1,1);sourceCtx.drawImage(video,(vw-crop.w)/2,(vh-crop.h)/2,crop.w,crop.h,0,0,640,360);sourceCtx.restore()}else if(demoActive&&demoImage?.complete&&demoImage.naturalWidth>0){const iw=demoImage.naturalWidth,ih=demoImage.naturalHeight,ch=iw*9/16;sourceCtx.drawImage(demoImage,0,Math.max(0,(ih-ch)*.35),iw,ch,0,0,640,360)}else if(!active){drawIdle();frame=requestAnimationFrame(render);return}const image=sourceCtx.getImageData(0,0,640,360);const mesh=mode==='bronca'?GrungeDisplacement.mesh(t,Number(distortion.value),fieldX,fieldY):null;const data=mesh?GrungeDisplacement.warpMesh(image.data,640,360,mesh,warpBuffer):GrungeDisplacement.warp(image.data,640,360,t,Number(distortion.value),fieldX,fieldY,warpBuffer);image.data.set(data);const pixels=image.data,contrast=1+Number(strength.value)/65,noise=Number(grain.value)*.0012;for(let y=0;y<360;y++){for(let x=0;x<640;x++){const i=(y*640+x)*4;let v=(pixels[i]*.299+pixels[i+1]*.587+pixels[i+2]*.114)/255;v=Math.max(0,Math.min(1,(v-.45)*contrast+.5));v=Math.round(v*22)/22;const paletteIndex=Math.min(255,Math.round(v*255))*3;const n=(Math.random()-.5)*noise*255,scan=y%3===0?.95:1;for(let c=0;c<3;c++)pixels[i+c]=lut[paletteIndex+c]*scan+n}}ctx.putImageData(image,0,0);if(mesh)drawBronca(mesh,t)}frame=requestAnimationFrame(render)}

  const doodles=new Map();
  function loadDoodles(){
    if(doodles.size)return;
    for(const number of [4,8,14]){
      const img=new Image();
      img.onload=()=>{
        const makeTint=ink=>{
          const layer=document.createElement('canvas');layer.width=img.naturalWidth;layer.height=img.naturalHeight;
          const paint=layer.getContext('2d');paint.drawImage(img,0,0);paint.globalCompositeOperation='source-in';paint.fillStyle=ink;paint.fillRect(0,0,layer.width,layer.height);return layer;
        };
        doodles.set(number,{white:makeTint('#f3f1e9'),red:makeTint('#ed3529')});
      };
      doodles.set(number,null);img.src='assets/doodles/grafismo-'+number+'.png';
    }
  }
  function drawBronca(mesh,time){
    const {cols,rows,points}=mesh,t=time/1000;
    ctx.save();ctx.strokeStyle='#ed3529';ctx.lineWidth=.65;ctx.globalAlpha=.2;
    const at=(x,y)=>points[y*(cols+1)+x];
    const vertex=p=>[(p.x-p.dx)*640,(p.y-p.dy)*360];
    // Líneas discretas: hacen visible la malla sin tapar la cara.
    for(let y=1;y<rows;y++)for(let x=1;x<cols;x++){
      const a=at(x,y);
      if(Math.hypot((a.x-fieldX)/.28,(a.y-fieldY)/.45)>1)continue;
      const [ax,ay]=vertex(a);ctx.beginPath();ctx.moveTo(ax,ay);
      const [bx,by]=vertex(at(x+1,y));ctx.lineTo(bx,by);ctx.moveTo(ax,ay);
      const [cx,cy]=vertex(at(x,y+1));ctx.lineTo(cx,cy);ctx.stroke();
    }
    ctx.restore();
    const stamp=(number,color,x,y,width,angle)=>{
      const layer=doodles.get(number)?.[color];if(!layer)return;
      const height=width*layer.height/layer.width;
      ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.globalAlpha=.9;
      ctx.drawImage(layer,-width/2,-height/2,width,height);ctx.restore();
    };
    const cx=fieldX*640,cy=fieldY*360;
    stamp(4,'red',cx+100+Math.sin(t*.9)*5,cy-55,37,-.22);
    stamp(14,'white',cx-115,cy+30+Math.sin(t*.7)*4,84,.15);
    stamp(8,'red',cx+65,cy+98,87,-.3);
  }
  function setState(on){active=on;start.textContent=on?'APAGAR CÁMARA ×':'PRENDER CÁMARA ↗';capture.disabled=!on&&!demoActive;freeze.disabled=!on&&!demoActive;document.querySelector('#camera-signal').textContent=on?'● EN VIVO / LOCAL':demoActive?'○ FOTO DE PRUEBA / ANIMADA':'○ CÁMARA APAGADA';document.querySelector('#raw-label').textContent=on?'ORIGINAL / EN VIVO':'CÁMARA APAGADA';document.querySelector('.raw-preview').classList.toggle('is-live',on)}
  function stop(){session++;demoActive=false;stream?.getTracks().forEach(track=>track.stop());stream=null;if(video)video.srcObject=null;frozen=false;if(freeze)freeze.textContent='CONGELAR';if(start)setState(false)}
  async function toggle(){if(active){stop();status.textContent='Cámara apagada. Podés volver a prenderla cuando quieras.';return}if(!navigator.mediaDevices?.getUserMedia){status.textContent='Este navegador no permite acceder a la cámara. Abrí localhost en Chrome o Edge.';return}demoActive=false;const ticket=++session;start.disabled=true;status.textContent='Esperando permiso para usar tu cámara…';try{const incoming=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:'user',width:{ideal:1280},height:{ideal:720}}});if(ticket!==session){incoming.getTracks().forEach(track=>track.stop());return}stream=incoming;video.srcObject=stream;await video.play();if(ticket!==session)return;setState(true);status.textContent='Estás en vivo. Mirá al centro y movete despacio.';stream.getVideoTracks()[0].addEventListener('ended',()=>{if(ticket===session){stop();status.textContent='La cámara se desconectó. Podés volver a intentar.'}},{once:true})}catch(error){if(ticket!==session)return;stop();status.textContent=({NotAllowedError:'No se habilitó el acceso. Permití la cámara desde el navegador y volvé a intentar.',NotFoundError:'No encontramos una cámara conectada.',NotReadableError:'La cámara está ocupada por otra aplicación. Cerrala y volvé a intentar.'})[error.name]||'No pudimos iniciar la cámara. Revisá la conexión y volvé a intentar.'}finally{if(start&&document.body.contains(start))start.disabled=false}}
  function init(){canvas=document.querySelector('#portrait-canvas');ctx=canvas.getContext('2d');video=document.querySelector('#camera-video');source=document.createElement('canvas');source.width=640;source.height=360;sourceCtx=source.getContext('2d',{willReadFrequently:true});status=document.querySelector('#camera-status');start=document.querySelector('#camera-start');capture=document.querySelector('#camera-capture');freeze=document.querySelector('#camera-freeze');strength=document.querySelector('#camera-strength');grain=document.querySelector('#camera-grain');distortion=document.querySelector('#camera-distortion');warpBuffer=new Uint8ClampedArray(640*360*4);fieldX=.5;fieldY=.46;demoButton=document.querySelector('#camera-demo');demoImage=new Image();demoImage.src="assets/retrato-fondo.png";demoButton.onclick=()=>{stop();demoActive=true;setState(false);status.textContent="Foto de prueba animada. No se está usando tu cámara.";};canvas.onpointermove=e=>{const r=canvas.getBoundingClientRect();fieldX=(e.clientX-r.left)/r.width;fieldY=(e.clientY-r.top)/r.height;};canvas.onpointerleave=()=>{fieldX=.5;fieldY=.46;};loadDoodles();mode='ash';updatePalette();frozen=false;active=false;last=0;start.onclick=toggle;freeze.onclick=()=>{frozen=!frozen;freeze.textContent=frozen?'VOLVER AL VIVO':'CONGELAR';document.querySelector('#camera-signal').textContent=frozen?'Ⅱ RETRATO CONGELADO':active?'● EN VIVO / LOCAL':'○ FOTO DE PRUEBA / ANIMADA'};capture.onclick=()=>{if(!active&&!demoActive)return;const a=document.createElement('a');a.download='el-odio-en-frances-mi-retrato.png';a.href=canvas.toDataURL('image/png');a.click();status.textContent='Retrato guardado en tu dispositivo.'};document.querySelectorAll('[data-palette]').forEach(button=>button.onclick=()=>{mode=button.dataset.palette;updatePalette();status.textContent=mode==='bronca'?'Modo bronca: malla de deformación y grafismos. Centrá tu cara; mové el cursor o tocá el visor para ubicar el efecto.':'Ceniza: retrato en blanco y negro.';document.querySelectorAll('[data-palette]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));if(frozen){frozen=false;freeze.textContent='CONGELAR';document.querySelector('#camera-signal').textContent=active?'● EN VIVO / LOCAL':demoActive?'○ FOTO DE PRUEBA / ANIMADA':'○ CÁMARA APAGADA'}});strength.oninput=()=>document.querySelector('#strength-value').textContent=strength.value+'%';distortion.oninput=()=>document.querySelector('#distortion-value').textContent=distortion.value+'%';grain.oninput=()=>document.querySelector('#grain-value').textContent=grain.value+'%';frame=requestAnimationFrame(render)}
  function destroy(){stop();cancelAnimationFrame(frame);canvas=null;ctx=null;video=null;start=null;capture=null;freeze=null;source=null;sourceCtx=null}
  document.addEventListener('visibilitychange',()=>{if(document.hidden&&canvas){stop();start.disabled=false;status.textContent='Cámara apagada al salir de la pantalla. Prendela para continuar.'}});
  window.addEventListener('pagehide',()=>{if(canvas)destroy()});
  return {markup,init,destroy};
})();
